refused_program.body:
upstream_ref="{upstream_remote}/{upstream_branch}"
merge_rc=0
if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git merge --no-edit --no-ff "$upstream_ref" || merge_rc=$?
fi
if [ "$merge_rc" -ne 0 ]; then
  git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1 || exit 1
fi
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
git diff --name-only --diff-filter=U -z | tr '\0' '\n' > "$tmp/conflicted"
while IFS= read -r path; do
  [ -n "$path" ] || continue
  git show ":1:$path" > "$tmp/base" 2>/dev/null || true
  git show ":2:$path" > "$tmp/ours" 2>/dev/null || true
  git show ":3:$path" > "$tmp/theirs" 2>/dev/null || true
  git merge-file -p --diff3 -q "$tmp/ours" "$tmp/base" "$tmp/theirs" > "$tmp/merged" 2>/dev/null || true
  awk -v T="$tmp" '
    BEGIN { state=0; no=0; nb=0; nt=0; ridx=0 }
    /^<<<<<<< / { state=1; no=0; nb=0; nt=0; split("", ours); split("", base); split("", theirs); next }
    /^\|\|\|\|\|\|\| / { state=2; next }
    /^=======$/ { state=3; next }
    /^>>>>>>> / {
      ridx++
      split("", isadd)
      if (nb == 0) {
        for (i=1;i<=nt;i++) isadd[theirs[i]]=1
      } else if (nt > 0) {
        bf = T "/rbase" ridx
        tf = T "/rtheirs" ridx
        for (i=1;i<=nb;i++) print base[i] > bf
        for (i=1;i<=nt;i++) print theirs[i] > tf
        close(bf); close(tf)
        cmd = "diff \"" bf "\" \"" tf "\""
        inadd = 0
        while ((cmd | getline ln) > 0) {
          if (ln ~ /^[0-9,]+a[0-9,]+$/) { inadd = 1; continue }
          if (ln ~ /^[0-9,]+[cd][0-9,]+$/) { inadd = 0; continue }
          if (ln ~ /^> /) { if (inadd) isadd[substr(ln,3)] = 1; continue }
        }
        close(cmd)
      }
      split("", os)
      for (i=1;i<=no;i++) { print ours[i]; os[ours[i]]=1 }
      for (i=1;i<=nt;i++) { l=theirs[i]; if (isadd[l] && !os[l]) { print l; os[l]=1 } }
      state=0
      next
    }
    {
      if (state==1) ours[++no]=$0
      else if (state==2) base[++nb]=$0
      else if (state==3) theirs[++nt]=$0
      else print
    }
  ' "$tmp/merged" > "$tmp/resolved"
  cat "$tmp/resolved" > "$path"
  git add -- "$path"
done < "$tmp/conflicted"
if git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git commit --no-edit
fi
